// Builds skrzynka/index.html from skrzynka/body.html (the artifact source, without a document
// skeleton) by wrapping it in the same skeleton the artifact host adds.
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const dir = path.join(path.dirname(fileURLToPath(import.meta.url)), '..', 'skrzynka');
const body = fs.readFileSync(path.join(dir, 'body.html'), 'utf8');
const html = `<!doctype html>
<html lang="pl">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover">
<!-- Generated by tools/build-skrzynka.js from body.html. Do not edit by hand. -->
<style>:root{color-scheme:light}body{margin:0;font:14px system-ui}img{max-width:100%}[hidden]{display:none!important}</style>
</head>
<body>
${body}
</body>
</html>
`;
fs.writeFileSync(path.join(dir, 'index.html'), html);
console.log('skrzynka/index.html', html.length, 'bytes');
